import React, { useState } from 'react';
import { useManagerStore } from '../../../store/managerStore';
import QRScannerModal from '../../shared/QRScannerModal';
import { doc, runTransaction, serverTimestamp, collection } from 'firebase/firestore';
import { db } from '../../../firebase';
import { getCurrentTenant } from '../../../utils/tenantHelper';

export default function PartsIssueReceive({ user }) {
  const parts = useManagerStore(state => state.parts || []);
  
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [selectedPart, setSelectedPart] = useState(null);
  
  // Tryb: 'receive' (Przyjęcie) lub 'issue' (Wydanie)
  const [mode, setMode] = useState('issue');
  const [quantity, setQuantity] = useState('');
  const [unitPrice, setUnitPrice] = useState('');
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const handleScan = (text) => {
    try {
      setIsScannerOpen(false);
      const urlParams = new URLSearchParams(text.includes('?') ? text.split('?')[1] : text);
      const partId = urlParams.get('part') || text;
      const found = parts.find(p => p.id === partId);
      if (found) {
        setSelectedPart(found);
        setUnitPrice(found.unitPrice || 0);
        setQuantity('');
      } else {
        alert("Nie znaleziono części o kodzie: " + partId);
      }
    } catch (err) {
      alert("Błąd skanowania kodu QR.");
    }
  };

  const handleManualSelect = (p) => {
    setSelectedPart(p);
    setUnitPrice(p.unitPrice || 0);
    setQuantity('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedPart) return;
    const qtyNum = Number(quantity);
    if (qtyNum <= 0) {
      alert("Ilość musi być większa od zera.");
      return;
    }

    setLoading(true);
    try {
      const tenantId = getCurrentTenant();
      const partRef = doc(db, 'tenants', tenantId, 'parts', selectedPart.id);
      const txRef = doc(collection(db, 'tenants', tenantId, 'part_transactions')); // new doc ref

      await runTransaction(db, async (transaction) => {
        const partDoc = await transaction.get(partRef);
        if (!partDoc.exists()) {
          throw new Error("Część nie istnieje.");
        }
        const currentStock = Number(partDoc.data().stock || 0);
        
        let newStock = currentStock;
        let finalPrice = Number(unitPrice);
        let txQuantity = qtyNum;

        if (mode === 'receive') {
          newStock = currentStock + qtyNum;
        } else if (mode === 'issue') {
          newStock = currentStock - qtyNum;
          txQuantity = -qtyNum; // zapis w historii jako ujemny
          finalPrice = Number(partDoc.data().unitPrice || 0); // wydanie po starej cenie
        }

        // Zapis do części
        const updatePayload = { stock: newStock };
        if (mode === 'receive') updatePayload.unitPrice = finalPrice; // aktualizacja ceny przy dostawie
        
        transaction.update(partRef, updatePayload);

        // Zapis do part_transactions
        transaction.set(txRef, {
          partId: selectedPart.id,
          type: mode === 'receive' ? 'receive' : 'issue_adhoc',
          quantity: txQuantity,
          price: finalPrice,
          date: new Date().toISOString(),
          user: user?.name || 'Nieznany (App)',
          createdAt: serverTimestamp()
        });
      });

      alert(mode === 'receive' ? 'Przyjęto na magazyn.' : 'Wydano z magazynu.');
      setSelectedPart(null);
      setQuantity('');
    } catch (err) {
      console.error(err);
      alert("Błąd operacji: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const filteredParts = parts.filter(p => {
    if (!searchQuery) return false; // pokaż tylko jak szuka
    const q = searchQuery.toLowerCase();
    return (p.name || '').toLowerCase().includes(q) || (p.code || '').toLowerCase().includes(q);
  }).slice(0, 5); // max 5 wyników ręcznych

  return (
    <div className="w-full space-y-4 pb-20">
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-xl font-black text-slate-800 tracking-tight">Szybkie Wydania i Przyjęcia</h2>
          <p className="text-sm text-slate-500 mt-1">Skanuj kody z kuwet, by natychmiast uaktualnić stan fizyczny.</p>
        </div>
        <button onClick={() => setIsScannerOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-5 py-3 rounded-xl font-bold shadow-md transition-all flex items-center gap-2">
          <i className="ph ph-qr-code text-xl"></i>
          Skanuj QR
        </button>
      </div>

      {!selectedPart && (
        <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100">
          <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Lub wyszukaj ręcznie</label>
          <div className="relative">
            <i className="ph ph-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-lg"></i>
            <input
              type="text"
              placeholder="Wpisz nazwę lub kod części..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium text-slate-700"
            />
          </div>
          {searchQuery && (
            <div className="mt-2 flex flex-col gap-2">
              {filteredParts.length === 0 ? (
                <div className="text-sm text-slate-500 p-2">Brak wyników.</div>
              ) : (
                filteredParts.map(p => (
                  <div key={p.id} onClick={() => handleManualSelect(p)} className="p-3 bg-slate-50 border border-slate-100 hover:border-blue-500 rounded-xl cursor-pointer transition-colors flex justify-between items-center group">
                    <div>
                      <div className="font-bold text-slate-800 group-hover:text-blue-600">{p.name}</div>
                      <div className="text-xs text-slate-400">KOD: {p.code || '-'}</div>
                    </div>
                    <div className="text-xs font-black text-slate-400 bg-white px-2 py-1 rounded shadow-sm border border-slate-100">
                      Na stanie: {p.stock}
                    </div>
                  </div>
                ))
              )}
            </div>
          )}
        </div>
      )}

      {selectedPart && (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 sm:p-8 animate-fade-in relative overflow-hidden">
          <button onClick={() => setSelectedPart(null)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-700 w-8 h-8 flex items-center justify-center bg-slate-50 rounded-full">
            <i className="ph ph-x"></i>
          </button>
          
          <div className="flex items-center gap-4 mb-6">
            <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-3xl shrink-0">
              <i className="ph ph-nut"></i>
            </div>
            <div>
              <h3 className="text-2xl font-black text-slate-800 leading-tight">{selectedPart.name}</h3>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mt-1">Aktualny stan: <span className="text-blue-600">{selectedPart.stock} szt.</span></p>
            </div>
          </div>

          <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
            <button onClick={() => setMode('issue')} className={`flex-1 py-3 text-sm font-bold rounded-lg transition-colors ${mode === 'issue' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500 hover:text-slate-700'}`}>
              <i className="ph ph-minus-circle mr-2 text-red-500"></i> Wydaj
            </button>
            <button onClick={() => setMode('receive')} className={`flex-1 py-3 text-sm font-bold rounded-lg transition-colors ${mode === 'receive' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-500 hover:text-slate-700'}`}>
              <i className="ph ph-plus-circle mr-2 text-emerald-500"></i> Przyjmij (Dostawa)
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Ilość sztuk *</label>
                <input 
                  type="number" min="1" step="1" required 
                  value={quantity} onChange={e => setQuantity(e.target.value)} 
                  className="w-full p-4 text-2xl font-black text-slate-800 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-center" 
                />
              </div>
              {mode === 'receive' && (
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Aktualizacja Ceny (PLN)</label>
                  <input 
                    type="number" min="0" step="0.01" required 
                    value={unitPrice} onChange={e => setUnitPrice(e.target.value)} 
                    className="w-full p-4 text-xl font-bold text-slate-800 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-center" 
                  />
                  <p className="text-[10px] text-slate-400 text-center mt-2">Zastąpi obecną cenę {selectedPart.unitPrice || 0} PLN w systemie.</p>
                </div>
              )}
            </div>

            <button type="submit" disabled={loading} className={`w-full py-4 rounded-xl font-black text-lg text-white shadow-md transition-all ${loading ? 'opacity-50' : ''} ${mode === 'receive' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-red-500 hover:bg-red-600'}`}>
              {loading ? 'Przetwarzanie...' : mode === 'receive' ? `POTWIERDŹ PRZYJĘCIE (+${quantity || 0})` : `POTWIERDŹ WYDANIE (-${quantity || 0})`}
            </button>
          </form>
        </div>
      )}

      {isScannerOpen && (
        <QRScannerModal
          isOpen={isScannerOpen}
          onClose={() => setIsScannerOpen(false)}
          onScanSuccess={handleScan}
          title="Skanuj Część"
        />
      )}
    </div>
  );
}
