import React from 'react';
import { useManagerStore } from '../../../store/managerStore';
import { QRCodeCanvas } from 'qrcode.react';
import { getCurrentTenant } from '../../../utils/tenantHelper';

export default function PartsQRCodes() {
  const parts = useManagerStore(state => state.parts || []);
  const tenantId = getCurrentTenant();

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="w-full space-y-4">
      {/* Niewidoczne do druku: Nagłówek */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 print:hidden">
        <div>
          <h2 className="text-xl font-black text-slate-800 tracking-tight">Zestawienie Kodów QR</h2>
          <p className="text-sm text-slate-500 mt-1">Wydrukuj tę stronę i naklej kody na regały lub pudełka z częściami.</p>
        </div>
        <button onClick={handlePrint} className="bg-slate-800 hover:bg-slate-900 text-white px-5 py-2.5 rounded-xl font-bold shadow-md transition-all flex items-center gap-2">
          <i className="ph ph-printer text-lg"></i>
          Drukuj A4
        </button>
      </div>

      {parts.length === 0 ? (
        <div className="bg-white rounded-2xl border border-gray-100 p-12 text-center shadow-sm print:hidden">
          <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
            <i className="ph ph-qr-code text-3xl text-slate-300"></i>
          </div>
          <h3 className="text-lg font-bold text-slate-800 mb-1">Brak części w magazynie</h3>
          <p className="text-slate-500">Dodaj pierwszą część zapasową, aby wygenerować kody QR.</p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 print:shadow-none print:border-none print:p-0">
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 print:grid-cols-4 gap-6 print:gap-4">
            {parts.map(part => {
              const qrValue = `tenant=${tenantId}&part=${part.id}`;
              return (
                <div key={part.id} className="border border-slate-200 rounded-xl p-4 flex flex-col items-center text-center break-inside-avoid print:border-slate-300">
                  <QRCodeCanvas value={qrValue} size={100} level="M" />
                  <div className="mt-3 font-black text-slate-800 text-sm leading-tight">{part.name}</div>
                  <div className="text-[10px] font-bold text-slate-500 mt-1 uppercase tracking-widest">{part.code || '-'}</div>
                  {part.location && (
                    <div className="text-[10px] bg-slate-100 px-2 py-0.5 rounded mt-2 font-bold">{part.location}</div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Style dla druku wstrzyknięte bezpośrednio */}
      <style>{`
        @media print {
          @page { size: A4 portrait; margin: 10mm; }
          body * { visibility: hidden; }
          .print\\:hidden { display: none !important; }
          .bg-white { background: transparent !important; }
          /* Szukamy głównego kontenera druku */
          .grid { visibility: visible; position: absolute; left: 0; top: 0; width: 100%; }
          .grid * { visibility: visible; }
        }
      `}</style>
    </div>
  );
}
